<div class="page-header"><div><p class="eyebrow">Administration · Exporte</p><h1>Dokumentvorlagen</h1><p>Zentrale Kopf-/Fußzeilen-, Logo-, Seitenzahl- und Wasserzeichenkonfiguration.</p></div></div>
<?php foreach($templates as $t):?><form method="post" enctype="multipart/form-data" action="<?= e(url('admin/templates/'.$t['id'])) ?>" class="panel form-grid"><?= csrf_field() ?><div class="span-2 panel-header"><div><h2><?= e($t['template_name']) ?></h2><p><?= e($t['template_code']) ?></p></div><a class="button ghost compact" target="_blank" href="<?= e(url('admin/templates/'.$t['id'].'/preview')) ?>">Vorschau</a></div><label>Kopfzeile<input name="header_text" value="<?= e($t['header_text']??'') ?>"></label><label>Fußzeile<input name="footer_text" value="<?= e($t['footer_text']??'') ?>"></label><label>Wasserzeichen<input name="watermark_text" value="<?= e($t['watermark_text']??'') ?>"></label><?php $layout=(string)($t['settings']['layout']??'standard');?><label>Layout<select name="layout"><option value="standard" <?= $layout==='standard'?'selected':'' ?>>Standard</option><option value="compact" <?= $layout==='compact'?'selected':'' ?>>Kompakt</option></select></label><label>Logo PNG/JPEG<input type="file" name="logo" accept=".png,.jpg,.jpeg"><?php if($t['logo_path']):?><small>Logo ist hinterlegt.</small><?php endif;?></label><label class="check-row"><input type="checkbox" name="show_page_numbers" value="1" <?= $t['show_page_numbers']?'checked':'' ?>><span>Seitenzahlen anzeigen</span></label><div class="span-2 form-actions"><button class="button primary" type="submit">Vorlage speichern</button></div></form><?php endforeach;?>
